function handler(event) {
  var request = event.request;
  var uri = request.uri;

  if (uri === '/') {
    return request;
  }

  if (uri.endsWith('/')) {
    request.uri = uri.slice(0, -1) + '.html';
    return request;
  }

  if (!uri.includes('.')) {
    request.uri = uri + '.html';
  }

  return request;
}
